.alert{
  display:grid;
  grid-template-columns:auto minmax(0,1fr);
  column-gap:var(--s-3);
  row-gap:var(--s-1);
  align-items:center;
  padding:var(--s-3) var(--s-4);
  background:var(--obsidian-850);
  border:var(--bw-1) solid var(--obsidian-800);
  border-left:var(--bw-2) solid var(--primary-500);
  border-radius:var(--r-md);
  font-size:var(--t-small);
  color:var(--obsidian-200);
}
.alert-icon{
  grid-column:1;
  grid-row:1;
  width:16px;
  height:16px;
  color:var(--primary-400);
}
.alert-title{
  grid-column:2;
  grid-row:1;
  font-weight:600;
  color:var(--obsidian-100);
  min-width:0;
}
.alert-body{
  grid-column:2;
  grid-row:1;
  min-width:0;
  overflow-wrap:anywhere;
}
.alert:has(.alert-title) .alert-body{
  grid-column:1 / -1;
  grid-row:2;
}
.alert-success{
  border-left-color:var(--success);
}
.alert-success .alert-icon{
  color:var(--success);
}
.alert-warn{
  border-left-color:var(--warning);
}
.alert-warn .alert-icon{
  color:var(--warning);
}
.alert-danger{
  border-left-color:var(--danger);
}
.alert-danger .alert-icon{
  color:var(--danger);
}
.alert-info{
  border-left-color:var(--info);
}
.alert-info .alert-icon{
  color:var(--info);
}
